// spec: specs/search-filters.md (1.4) · кейс: .qa/tests/search-filters/FILTER-PRICE-04.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. Ручка макс у края (₪10,000,000) = «без ограничения».
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, captureCatalog, openPage, openFilter, fields, thumbs, rangeLabel, enter, applyFilter, idsInRange,
  expectResults, dragThumb, thumbCenters, fmt, priceOf, Biz, LOAD, PRICE_EDGE,
} from './search-filters.helpers';

test.use({ serviceWorkers: 'block' });

const MIN = 5_000_000;

function expectAboveEdge(catalog: Biz[], ids: string[]) {
  const above = catalog.filter((b) => ids.includes(b.id) && priceOf(b) > PRICE_EDGE);
  expect(above.length, `в каталоге есть активные объявления дороже ${fmt(PRICE_EDGE)} — иначе проверка невозможна (данные сайта)`).toBeGreaterThan(0);
}

test.describe('Фильтры поиска — макс у края = без ограничения', () => {
  for (const dev of [{ tag: '@desktop', popup: false }, { tag: '@android', popup: true }]) {
    test(`/search?minPrice=5000000 показывает и объявления дороже ₪10,000,000; поля и ручки по URL #b4b8c9 ${dev.tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      const catalog = captureCatalog(page);
      await openPage(page, `/search?minPrice=${MIN}`);
      const all = await catalog();
      const expected = idsInRange(all, MIN, null);
      expectAboveEdge(all, expected);
      await expectResults(page, expected, `?minPrice=${MIN}`);

      const scope = await openFilter(page, dev.popup);
      await expect(fields(scope).min).toHaveValue(String(MIN));
      await expect(fields(scope).max, 'макс не задан').toHaveValue('');
      await expect(rangeLabel(scope)).toHaveText(`${fmt(MIN)} - ${fmt(PRICE_EDGE)}`);
      await expect(thumbs(scope).max, 'ручка макс у края').toHaveAttribute('aria-valuenow', String(PRICE_EDGE));
    });

    test(`/search?minPrice=5000000&maxPrice=10000000 = без верхней границы #b4b8c9 ${dev.tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      const catalog = captureCatalog(page);
      await openPage(page, `/search?minPrice=${MIN}&maxPrice=${PRICE_EDGE}`);
      const all = await catalog();
      const expected = idsInRange(all, MIN, null);
      expectAboveEdge(all, expected);
      await expectResults(page, expected, `?minPrice=${MIN}&maxPrice=${PRICE_EDGE}`);
    });

    test(`Только мин в поле (5,000,000) → URL без maxPrice, видны объявления дороже ₪10,000,000 #b4b8c9 ${dev.tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      const catalog = captureCatalog(page);
      await openPage(page, '/search');
      const all = await catalog();
      const expected = idsInRange(all, MIN, null);
      expectAboveEdge(all, expected);

      const scope = await openFilter(page, dev.popup);
      await enter(fields(scope).min, MIN, 'type');
      await applyFilter(page);
      await page.waitForURL((u) => u.searchParams.get('minPrice') === String(MIN) && !u.searchParams.has('maxPrice'), LOAD);
      await expectResults(page, expected, `поле мин ${MIN}`);
    });
  }

  test('Попап: ручка мин до конца → ₪10,000,000 - ₪10,000,000, выдача — объявления от ₪10,000,000 и дороже, не «לא נמצאו» #b4b8c9 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    const catalog = captureCatalog(page);
    await openPage(page, '/search');
    const all = await catalog();
    const expected = idsInRange(all, PRICE_EDGE, null);
    expect(expected.length, `в каталоге есть объявления от ${fmt(PRICE_EDGE)} — иначе данные сайта`).toBeGreaterThan(0);

    const dialog = await openFilter(page, true);
    const t = thumbs(dialog);
    const { maxX } = await thumbCenters(dialog);
    await dragThumb(page, t.min, Math.max(1, maxX - 30));
    await expect(t.min).toHaveAttribute('aria-valuenow', String(PRICE_EDGE));
    await expect(rangeLabel(dialog)).toHaveText(`${fmt(PRICE_EDGE)} - ${fmt(PRICE_EDGE)}`);

    await applyFilter(page);
    await expect(dialog).toBeHidden(LOAD);
    await page.waitForURL((u) => u.searchParams.get('minPrice') === String(PRICE_EDGE) && !u.searchParams.has('maxPrice'), LOAD);
    await expectResults(page, expected, `мин у края ${PRICE_EDGE}`);
    await expect(page.getByText(/לא נמצאו/).filter({ visible: true }), 'нет «לא נמצאו»').toHaveCount(0);
  });
});
